mapper.select:
SELECT l.id AS log_id, d.id AS detail_id, l.change_date, l.project_id, l.project_name, l.project_path, l.file_path, l.flow_id, l.flow_longname, l.file_change_type, l.capture_status, l.error_message, d.io_type, d.field_path, d.field_id, d.change_type AS detail_change_type, d.changed_attributes, l.commit_sha, l.commit_message, l.commit_author, l.commit_email, l.commit_time FROM flow_field_change_log l LEFT JOIN flow_field_change_detail d ON d.log_id = l.id WHERE l.scan_run_id IS NOT NULL
AND l.project_id = #{query.projectId}
AND l.project_name LIKE CONCAT('%', #{query.projectName}, '%')
AND l.file_path LIKE CONCAT('%', #{query.filePath}, '%')
AND l.flow_id = #{query.flowId}
AND d.io_type = #{query.ioType}
AND BINARY d.field_id LIKE CONCAT('%', #{query.fieldId}, '%')
AND COALESCE(d.change_type, l.file_change_type) = #{query.changeType}
AND l.commit_author LIKE CONCAT('%', #{query.commitAuthor}, '%')
AND l.capture_status = #{query.captureStatus}
AND l.change_date >= #{query.startDate}
AND l.change_date <= #{query.endDate}
ORDER BY l.commit_time DESC, l.id DESC, d.id ASC

SELECT r.id, r.project_id, r.project_name, r.project_path, r.branch, r.window_start, r.window_end, r.status, r.commit_count, r.changed_file_count, r.history_count, r.failed_file_count, r.skipped_count, r.cursor_advanced, r.error_message, r.started_at, r.finished_at FROM flow_field_scan_run r WHERE 1 = 1
AND r.project_id = #{query.projectId}
AND r.status = #{query.status}
AND DATE(r.window_end) >= #{query.startDate}
AND DATE(r.window_end) <= #{query.endDate}
ORDER BY r.window_end DESC, r.id DESC
